package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.Base64Variant;
import com.fasterxml.jackson.databind.cfg.ClassIntrospector;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.PropertyNamingStrategy;
import com.fasterxml.jackson.databind.cfg.TypeFactory;
import com.fasterxml.jackson.databind.cfg.TypeResolverBuilder;
import com.fasterxml.jackson.databind.cfg.VisibilityChecker;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector;
import com.fasterxml.jackson.databind.introspect.VisibilityChecker;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.when;

public class BaseSettings_withDateFormat_TriageGen2Test {

    private ClassIntrospector _classIntrospector;
    private AnnotationIntrospector _annotationIntrospector;
    private VisibilityChecker<?> _visibilityChecker;
    private PropertyNamingStrategy _propertyNamingStrategy;
    private TypeFactory _typeFactory;
    private TypeResolverBuilder<?> _typeResolverBuilder;
    private HandlerInstantiator _handlerInstantiator;
    private Locale _locale;
    private TimeZone _timeZone;
    private Base64Variant _defaultBase64;
    private BaseSettings _baseSettings;

    @Before
    public void setUp() {
        _classIntrospector = Mockito.mock(ClassIntrospector.class);
        _annotationIntrospector = Mockito.mock(AnnotationIntrospector.class);
        _visibilityChecker = Mockito.mock(VisibilityChecker.class);
        _propertyNamingStrategy = Mockito.mock(PropertyNamingStrategy.class);
        _typeFactory = Mockito.mock(TypeFactory.class);
        _typeResolverBuilder = Mockito.mock(TypeResolverBuilder.class);
        _handlerInstantiator = Mockito.mock(HandlerInstantiator.class);
        _locale = Locale.US;
        _timeZone = TimeZone.getDefault();
        _defaultBase64 = Base64Variant.of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/");

        _baseSettings = new BaseSettings(
                _classIntrospector, _annotationIntrospector, _visibilityChecker, _propertyNamingStrategy, _typeFactory,
                _typeResolverBuilder, null, _handlerInstantiator, _locale, _timeZone, _defaultBase64
        );
    }

    @Test
    public void testWithDateFormat_SameInstanceReturnsThis() {
        DateFormat df = Mockito.mock(DateFormat.class);
        // We need to create a baseSettings that already has this specific df to trigger the if (_dateFormat == df)
        BaseSettings existingSettings = new BaseSettings(
                _classIntrospector, _annotationIntrospector, _visibilityChecker, _propertyNamingStrategy, _typeFactory,
                _typeResolverBuilder, df, _handlerInstantiator, _locale, _timeZone, _defaultBase64
        );

        BaseSettings result = existingSettings.withDateFormat(df);

        assertSame("Should return the same instance when DateFormat is identical", existingSettings, result);
    }

    @Test
    public void testWithDateFormat_NullDateFormatUsesExistingTimeZone() {
        DateFormat df = null;

        BaseSettings result = _baseSettings.withDateFormat(df);

        assertEquals("New DateFormat should be null", null, result.getDateFormat());
        assertEquals("TimeZone should be preserved from original settings", _timeZone, result.getTimeZone());
        // Verify other properties are preserved
        assertSame(_classIntrospector, result.getClassIntrospector());
        assertSame(_locale, result.getLocale());
        assertSame(_defaultBase64, result.getBase64Variant());
    }

    @Test
    public void testWithDateFormat_NewDateFormatUsesItsOwnTimeZone() {
        DateFormat df = Mockito.mock(DateFormat.class);
        TimeZone newTz = TimeZone.getTimeZone("UTC");
        when(df.getTimeZone()).thenReturn(newTz);

        BaseSettings result = _baseSettings.withDateFormat(df);

        assertEquals("New DateFormat should be the provided one", df, result.getDateFormat());
        assertEquals("TimeZone should be taken from the new DateFormat", newTz, result.getTimeZone());
        // Verify other properties are preserved
        assertSame(_classIntrospector, result.getClassIntrospector());
        assertSame(_timeZone, result.getTimeZone()); // original tz is replaced by newTz
        assertSame(_locale, result.getLocale());
    }

    @Test
    public void testWithDateFormat_DifferentDateFormatCreatesNewInstance() {
        DateFormat df1 = Mockito.mock(DateFormat.class);
        DateFormat df2 = Mockito.mock(DateFormat.class);
        when(df1.getTimeZone()).thenReturn(_timeZone);
        when(df2.getTimeZone()).thenReturn(_timeZone);

        BaseSettings settings1 = _baseSettings.withDateFormat(df1);
        BaseSettings settings2 = settings1.withDateFormat(df2);

        assertNotSame("Should create a new instance when DateFormat is different", settings1, settings2);
        assertEquals(df2, settings2.getDateFormat());
    }
}
